<template>
  <div class="im-workspace">
    <aside class="conversations"><div class="office-toolbar"><h2>消息</h2><el-button circle title="新建会话" @click="newVisible=true"><span class="material-symbols-outlined">edit_square</span></el-button></div><el-input v-model="query" placeholder="搜索会话" clearable/><el-select v-model="groupFilter" placeholder="全部分组" clearable><el-option v-for="g in groups" :key="g" :label="g" :value="g"/></el-select>
      <div class="conversation-list"><button v-for="c in filteredConversations" :key="c.sessionId" :class="['conversation',{active:c.sessionId===selected?.sessionId}]" @click="select(c)"><span class="conversation-avatar">{{ (c.name||'聊').slice(0,1) }}</span><span class="conversation-body"><strong>{{ c.pinned?'↑ ':'' }}{{ c.name }}{{ c.muted?' · 静音':'' }}</strong><small>{{ c.draft?'[草稿] '+c.draft:c.lastMsg?.startsWith('{')?'[文件]':c.lastMsg||'暂无消息' }}</small></span><el-badge v-if="c.unreadCount&&!c.muted" :value="c.unreadCount" :max="99"/></button><div v-if="!conversations.length" class="office-empty">暂无会话</div></div>
    </aside>
    <section v-if="selected" class="chat-panel">
      <header class="chat-header"><strong>{{ selected.name }}</strong><span class="office-muted connection">{{ connected?'已连接':'连接中' }}</span><el-button circle title="搜索消息" @click="searchVisible=true"><span class="material-symbols-outlined">search</span></el-button><el-button circle title="会话设置" @click="openSettings"><span class="material-symbols-outlined">settings</span></el-button></header>
      <p v-if="sessionInfo?.announcement" class="announcement">公告：{{ sessionInfo.announcement }}</p>
      <div v-if="sessionInfo?.pins?.length" class="announcement"><div v-for="p in sessionInfo.pins" :key="p.msgId" class="office-toolbar"><span>置顶：{{ quoteText(p.content) }}</span><el-button v-if="manager" text @click="pinMessage(p,false)">取消置顶</el-button></div></div>
      <div ref="scrollArea" class="chat-messages" v-loading="loading"><el-button v-if="hasMore" text @click="older">加载更早消息</el-button>
        <article v-for="m in messages" :key="m.msgId" :id="'message-'+m.msgId" :class="['chat-message',{own:String(m.senderId)===userId}]"><div class="office-muted">{{ m.senderName||'团队成员' }} · {{ String(m.sendTime||'').replace('T',' ').slice(0,19) }}</div><div class="message-content"><blockquote v-if="m.quote&&!m.isRecalled">{{ quoteText(m.quote) }}</blockquote><span v-if="m.isRecalled">此消息已撤回</span><button v-else-if="m.msgType===3&&attachment(m).fileId" class="office-link attachment" @click="download(m)"><span class="material-symbols-outlined">attach_file</span>{{ attachment(m).fileName||'文件' }}</button><span v-else>{{ m.content }}</span></div>
          <div v-if="!m.isRecalled" class="message-actions"><small class="office-muted">{{ m.isEdited?'已编辑 · ':'' }}{{ String(m.senderId)===userId?'已读 '+m.readCount:'' }}</small><el-button circle title="引用回复" size="small" @click="reply=m"><span class="material-symbols-outlined">reply</span></el-button><el-button circle title="转发消息" size="small" @click="forwarding=m;forwardVisible=true"><span class="material-symbols-outlined">forward</span></el-button><el-button v-if="selected.type===2&&manager" circle title="置顶消息" size="small" @click="pinMessage(m,true)"><span class="material-symbols-outlined">push_pin</span></el-button><el-button v-if="String(m.senderId)===userId&&m.msgType===1" circle title="编辑消息" size="small" @click="editMessage(m)"><span class="material-symbols-outlined">edit</span></el-button><el-button v-if="String(m.senderId)===userId&&canRecall(m)" circle title="撤回消息" size="small" @click="recall(m)"><span class="material-symbols-outlined">undo</span></el-button></div>
        </article><el-empty v-if="!messages.length" description="暂无消息" :image-size="50"/>
      </div>
      <form class="chat-compose" @submit.prevent="send" @paste="pasteImage"><div v-if="reply" class="reply-preview"><span>回复 {{ reply.senderName }}：{{ quoteText(reply.content) }}</span><el-button circle title="取消回复" size="small" @click="reply=undefined"><span class="material-symbols-outlined">close</span></el-button></div><el-input v-model="text" type="textarea" :rows="3" resize="none" maxlength="10000" placeholder="发送消息"/><div class="office-toolbar"><el-button v-if="selected.type===2&&selected.role==='OWNER'" circle title="解散群组" @click="dissolve"><span class="material-symbols-outlined">group_off</span></el-button><el-button circle title="发送文件或图片" :loading="sending" @click="fileInput?.click()"><span class="material-symbols-outlined">attach_file</span></el-button><input ref="fileInput" type="file" hidden @change="sendFile"/><el-dropdown><el-button circle title="提及成员"><span class="material-symbols-outlined">alternate_email</span></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="selected.type===2" @click="text+=' @all '">全体成员</el-dropdown-item><el-dropdown-item v-for="m in sessionInfo?.members||[]" :key="m.userId" @click="text+=' @'+m.userId+' '">{{ m.name }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button type="primary" native-type="submit" :loading="sending" :disabled="!text.trim()">发送</el-button></div></form>
    </section><el-empty v-else description="选择一个会话" class="chat-placeholder"/>
    <el-dialog v-model="newVisible" title="新建会话" width="min(450px,94vw)"><form class="office-form" @submit.prevent="createSession"><label>会话类型<el-radio-group v-model="newType"><el-radio :value="1">单聊</el-radio><el-radio :value="2">群聊</el-radio></el-radio-group></label><label v-if="newType===2">群名称<el-input v-model="newName" maxlength="100"/></label><label>成员<el-select v-model="newMembers" multiple filterable :multiple-limit="newType===1?1:100"><el-option v-for="m in members.filter(m=>String(m.userId)!==userId)" :key="m.userId" :label="m.userName" :value="String(m.userId)"/></el-select></label><el-button type="primary" native-type="submit" :loading="sending">创建会话</el-button></form></el-dialog>
    <el-dialog v-model="searchVisible" title="消息搜索" width="min(680px,94vw)"><form class="office-toolbar" @submit.prevent="search"><el-input v-model="messageQuery" placeholder="输入消息关键词" maxlength="100" clearable/><el-button native-type="submit" type="primary">搜索</el-button></form><div class="search-results"><button v-for="m in results" :key="m.msgId" class="search-result" @click="jump(m)"><strong>{{ m.senderName }} · {{ String(m.sendTime).replace('T',' ') }}</strong><p>{{ quoteText(m.content) }}</p></button><el-empty v-if="searched&&!results.length" description="未找到消息"/></div></el-dialog>
    <el-dialog v-model="forwardVisible" title="转发消息" width="min(440px,94vw)"><el-select v-model="forwardTarget" placeholder="选择目标会话" filterable><el-option v-for="c in conversations" :key="c.sessionId" :label="c.name" :value="c.sessionId"/></el-select><template #footer><el-button type="primary" :disabled="!forwardTarget" @click="forward">转发</el-button></template></el-dialog>
    <el-dialog v-model="settingsVisible" title="会话设置" width="min(620px,94vw)"><div v-if="selected" class="office-form"><label>置顶<el-switch :model-value="!!selected.pinned" @change="preference({pinned:!!$event})"/></label><label>免打扰<el-switch :model-value="!!selected.muted" @change="preference({muted:!!$event})"/></label><label>分组<el-input v-model="sessionGroup" maxlength="50" @change="preference({groupName:sessionGroup})"/></label><el-button @click="exportChat">导出当前会话记录</el-button><template v-if="selected.type===2"><label>群名称<el-input v-model="sessionName" maxlength="100" :disabled="!manager"/></label><label>群公告<el-input v-model="announcement" type="textarea" :rows="3" maxlength="5000" :disabled="!manager"/></label><el-button v-if="manager" @click="saveGroup">保存群资料</el-button><div class="members"><div v-for="m in sessionInfo?.members||[]" :key="m.userId" class="member-row"><span>{{ m.name }} · {{ ({OWNER:'群主',ADMIN:'管理员',MEMBER:'成员'} as any)[m.role] }}</span><el-button v-if="selected.role==='OWNER'&&m.role!=='OWNER'" text @click="setRole(m)">{{ m.role==='ADMIN'?'撤销管理员':'设为管理员' }}</el-button><el-button v-if="selected.role==='OWNER'&&m.role!=='OWNER'" text @click="transfer(m)">转让</el-button><el-button v-if="manager&&m.role!=='OWNER'&&String(m.userId)!==userId" text type="danger" @click="removeMember(m)">移除</el-button></div></div><div v-if="manager" class="office-toolbar"><el-select v-model="invitee" placeholder="邀请成员" filterable><el-option v-for="m in members.filter(m=>!sessionInfo?.members?.some((s:any)=>String(s.userId)===String(m.userId)))" :key="m.userId" :label="m.userName" :value="String(m.userId)"/></el-select><el-button :disabled="!invitee" @click="invite">邀请</el-button></div><el-button v-if="selected.role!=='OWNER'" type="danger" plain @click="leave">退出群聊</el-button><h4>群文件</h4><button v-for="m in sessionInfo?.files||[]" :key="m.msgId" class="office-link attachment" @click="download(m)">{{ attachment(m).fileName }}</button></template></div></el-dialog>
  </div>
</template>
<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
import {getToken} from '@/utils/token'
import {downloadFile} from '@/utils/download'
import {wsClient} from '@/utils/wsClient'
import {useWorkspaceStore} from '@/stores/workspace'
import {useRoute} from 'vue-router'
const route=useRoute()
const workspace=useWorkspaceStore(),conversations=ref<any[]>([]),members=ref<any[]>([]),selected=ref<any>(),messages=ref<any[]>([]),userId=ref(''),text=ref(''),query=ref(''),groupFilter=ref(''),loading=ref(false),sending=ref(false),connected=ref(false),scrollArea=ref<HTMLElement>(),fileInput=ref<HTMLInputElement>(),page=ref(1),hasMore=ref(false)
const newVisible=ref(false),newType=ref(2),newName=ref(''),newMembers=ref<string[]>([]),reply=ref<any>(),searchVisible=ref(false),messageQuery=ref(''),results=ref<any[]>([]),searched=ref(false),forwarding=ref<any>(),forwardVisible=ref(false),forwardTarget=ref(''),settingsVisible=ref(false),sessionInfo=ref<any>(),sessionName=ref(''),sessionGroup=ref(''),announcement=ref(''),invitee=ref('')
const groups=computed(()=>[...new Set(conversations.value.map(c=>c.groupName).filter(Boolean))] as string[])
const filteredConversations=computed(()=>conversations.value.filter(c=>c.name?.includes(query.value)&&(!groupFilter.value||c.groupName===groupFilter.value)).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||String(b.lastMsgTime||'').localeCompare(String(a.lastMsgTime||''))))
const manager=computed(()=>['OWNER','ADMIN'].includes(selected.value?.role))
let unsubscribe:(()=>void)|undefined,unsubscribeStatus:(()=>void)|undefined,poll:ReturnType<typeof setInterval>|undefined,draftTimer:ReturnType<typeof setTimeout>|undefined,disposed=false,changing=false
async function loadConversations(){const r:any=await request.get('/chat/conversations');if(!disposed){conversations.value=r.data;if(selected.value){const c=r.data.find((c:any)=>c.sessionId===selected.value.sessionId);if(c)selected.value=c}}}
function sortMessages(list:any[]){return list.sort((a,b)=>String(a.sendTime).localeCompare(String(b.sendTime))||String(a.msgId).localeCompare(String(b.msgId)))}
async function history(append=false){if(!selected.value)return;const id=selected.value.sessionId;const r:any=await request.get('/chat/messages/'+id,{params:{size:50,page:append?page.value:1}});if(selected.value?.sessionId!==id||disposed)return;if(append){const ids=new Set(messages.value.map(m=>m.msgId));messages.value=sortMessages([...r.data.filter((m:any)=>!ids.has(m.msgId)),...messages.value])}else{const ids=new Set(r.data.map((m:any)=>m.msgId));messages.value=sortMessages([...messages.value.filter(m=>!ids.has(m.msgId)),...r.data]);hasMore.value=page.value>1||r.data.length===50}await request.post('/chat/read/'+id);const c=conversations.value.find(c=>c.sessionId===id);if(c)c.unreadCount=0;if(append)hasMore.value=r.data.length===50}
async function older(){page.value++;try{await history(true)}catch{page.value--}}
async function flushDraft(){if(draftTimer)clearTimeout(draftTimer);if(selected.value)await request.put(`/chat/sessions/${selected.value.sessionId}/preferences`,{draft:text.value})}
async function select(c:any){if(!c)return;if(selected.value)await flushDraft();changing=true;selected.value=c;text.value=c.draft||'';messages.value=[];reply.value=undefined;sessionInfo.value=undefined;page.value=1;loading.value=true;try{await history();const r:any=await request.get(`/chat/sessions/${c.sessionId}`);sessionInfo.value=r.data;await bottom()}catch{}finally{loading.value=false;await nextTick();changing=false}}
watch(text,()=>{if(changing||!selected.value)return;const id=selected.value.sessionId;if(draftTimer)clearTimeout(draftTimer);draftTimer=setTimeout(()=>{request.put(`/chat/sessions/${id}/preferences`,{draft:text.value}).catch(()=>{})},700)})
async function bottom(){await nextTick();scrollArea.value?.scrollTo({top:scrollArea.value.scrollHeight})}
async function refresh(){try{await loadConversations();await history()}catch{}}
async function deliver(content:string,msgType=1){await request.post('/chat/compose',{sessionId:selected.value.sessionId,content,msgType:String(msgType),replyToId:reply.value?.msgId});reply.value=undefined;await history();await loadConversations();await bottom()}
async function send(){if(!text.value.trim()||sending.value)return;sending.value=true;try{await deliver(text.value.trim());text.value='';await flushDraft()}catch{}finally{sending.value=false}}
async function sendFile(event:Event){const f=(event.target as HTMLInputElement).files?.[0];if(!f)return;sending.value=true;try{const form=new FormData();form.append('file',f);const r:any=await request.post('/file/upload',form,{timeout:120000});await deliver(JSON.stringify({fileId:r.data.fileId,fileName:f.name}),3)}catch{}finally{sending.value=false;if(fileInput.value)fileInput.value.value=''}}
async function pasteImage(event:ClipboardEvent){const f=Array.from(event.clipboardData?.files||[]).find(f=>f.type.startsWith('image/'));if(!f||sending.value)return;event.preventDefault();sending.value=true;try{const form=new FormData();form.append('file',f);const r:any=await request.post('/file/upload',form,{timeout:120000});await deliver(JSON.stringify({fileId:r.data.fileId,fileName:f.name}),3)}catch{}finally{sending.value=false}}
async function pinMessage(message:any,value:boolean){try{await request.put('/chat/pin/'+message.msgId,null,{params:{value}});const r:any=await request.get(`/chat/sessions/${selected.value.sessionId}`);sessionInfo.value=r.data}catch{}}
async function dissolve(){try{await ElMessageBox.confirm('解散后成员不能继续发送消息。确认解散此群？','解散群组',{type:'warning'});await request.delete(`/chat/sessions/${selected.value.sessionId}`);selected.value=undefined;await loadConversations()}catch{}}
function attachment(m:any){try{return JSON.parse(m.content)}catch{return {}}}
function quoteText(content:string){try{return JSON.parse(content).fileName||content}catch{return content}}
function canRecall(m:any){return Date.now()-new Date(m.sendTime).getTime()<120000}
async function download(m:any){const f=attachment(m);try{await downloadFile(f.fileId,f.fileName)}catch(e:any){if(!e.displayed)ElMessage.error(e.message)}}
async function recall(m:any){try{await request.post('/chat/recall/'+m.msgId);await refresh()}catch{}}
async function editMessage(m:any){try{const r=await ElMessageBox.prompt('消息内容','编辑消息',{inputValue:m.content,inputType:'textarea',inputValidator:v=>!!v?.trim()&&v.length<=10000});await request.put('/chat/edit/'+m.msgId,{content:r.value});await history()}catch{}}
async function search(){if(!messageQuery.value.trim())return;try{const r:any=await request.get('/chat/search',{params:{keyword:messageQuery.value.trim()}});results.value=r.data;searched.value=true}catch{}}
async function jump(m:any){await select(conversations.value.find(c=>c.sessionId===m.sessionId));while(!messages.value.some(x=>x.msgId===m.msgId)&&hasMore.value&&page.value<100)await older();searchVisible.value=false;await nextTick();document.getElementById('message-'+m.msgId)?.scrollIntoView({block:'center',behavior:'smooth'})}
async function forward(){try{await request.post('/chat/forward/'+forwarding.value.msgId,{sessionId:forwardTarget.value});forwardVisible.value=false;forwardTarget.value='';await refresh();ElMessage.success('已转发')}catch{}}
async function openSettings(){try{const r:any=await request.get(`/chat/sessions/${selected.value.sessionId}`);sessionInfo.value=r.data;sessionName.value=r.data.name;announcement.value=r.data.announcement||'';sessionGroup.value=selected.value.groupName||'';settingsVisible.value=true}catch{}}
async function preference(body:any){try{await request.put(`/chat/sessions/${selected.value.sessionId}/preferences`,body);await loadConversations()}catch{}}
async function saveGroup(){try{await request.put(`/chat/sessions/${selected.value.sessionId}`,{name:sessionName.value,announcement:announcement.value});await loadConversations();await openSettings();ElMessage.success('群资料已保存')}catch{}}
async function invite(){try{await request.post(`/chat/sessions/${selected.value.sessionId}/members`,{userId:invitee.value});invitee.value='';await openSettings()}catch{}}
async function setRole(m:any){try{await request.put(`/chat/sessions/${selected.value.sessionId}/members/${m.userId}`,{role:m.role==='ADMIN'?'MEMBER':'ADMIN'});await openSettings()}catch{}}
async function removeMember(m:any){try{await ElMessageBox.confirm(`移除 ${m.name}？`,'移除成员');await request.delete(`/chat/sessions/${selected.value.sessionId}/members/${m.userId}`);await openSettings()}catch{}}
async function transfer(m:any){try{await ElMessageBox.confirm(`将群主转让给 ${m.name}？`,'转让群组');await request.put(`/chat/sessions/${selected.value.sessionId}/owner/${m.userId}`);await loadConversations();await openSettings()}catch{}}
async function leave(){try{await ElMessageBox.confirm('确认退出当前群聊？','退出群聊');await request.delete(`/chat/sessions/${selected.value.sessionId}/members/${userId.value}`);selected.value=undefined;settingsVisible.value=false;await loadConversations()}catch{}}
async function exportChat(){try{const all:any[]=[];for(let p=1;p<=10000;p++){const r:any=await request.get('/chat/messages/'+selected.value.sessionId,{params:{page:p,size:500}});all.push(...r.data);if(r.data.length<500)break}const url=URL.createObjectURL(new Blob([JSON.stringify(sortMessages(all),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=selected.value.name+'-聊天记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}catch{}}
async function createSession(){if(!newMembers.value.length||newType.value===2&&!newName.value.trim()){ElMessage.warning('请选择成员并填写群名称');return}sending.value=true;try{const name=newType.value===1?members.value.find(m=>String(m.userId)===newMembers.value[0])?.userName:newName.value.trim();const r:any=await request.post('/chat/sessions',{type:newType.value,name,memberIds:newMembers.value});newVisible.value=false;newMembers.value=[];newName.value='';await loadConversations();await select(conversations.value.find(c=>c.sessionId===r.data))}catch{}finally{sending.value=false}}
onMounted(async()=>{try{const r:any[]=await Promise.all([request.get('/user/info'),request.get(`/space/${workspace.spaceId}/members`)]);userId.value=String(r[0].data.userId);members.value=r[1].data;await loadConversations();if(route.query.session){if(route.query.message)await jump({sessionId:String(route.query.session),msgId:String(route.query.message)});else await select(conversations.value.find(c=>c.sessionId===String(route.query.session)))}wsClient.connect(getToken()||undefined);unsubscribeStatus=wsClient.onStatusChange(c=>connected.value=c);unsubscribe=wsClient.on('chat_receive',async data=>{await loadConversations();if(data.sessionId===selected.value?.sessionId){await history();await bottom()}});poll=setInterval(()=>{if(!document.hidden)refresh()},10000)}catch{}})
onUnmounted(()=>{disposed=true;unsubscribe?.();unsubscribeStatus?.();if(poll)clearInterval(poll);if(draftTimer)clearTimeout(draftTimer)})
</script>
